head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[tabControl > E > onbeforetabmove]<br/>tabMove=true 일때 Tab 버튼을 DragDrop 하여 Tab 페이지의 순서가 변경되기 직전에 발생하며 반환값으로 취소할 수 있습니다.",
    "validation" : [
        "반환값으로 미설정 또는 true 설정 시  Tab 페이지의 순서를 변경한 후 onaftertabmove 이벤트를 발생시킵니다.",
        "반환값 false 설정 시 Tab 페이지의 순서 변경이 취소되고, DragDrop 된 Tab 버튼을 선택 처리합니다.",
        "Tab 버튼이 선택 처리될때 onbeforeselect 이벤트가 발생되며 onbeforeselect 이벤트의 반환값에 따라 선택이 취소되거나 onchange 이벤트가 발생합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {
        tabMove : true,
    }

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["onbeforetabmove", "onaftertabmove", "onbeforeselect", "onchange"]);

    $c.gcm.createBasicTabControl(cList, eList);

    scwin.getTabButtonInfo();
}



scwin.target1_onbeforetabmove = function (info) {
    let returnValue = par_return.getText();

    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onbeforetabmove=====");
    wf_body_bottom.getObj("scwin").setReturnValue("info.startTabIndex : " + info.startTabIndex);
    wf_body_bottom.getObj("scwin").setReturnValue("info.startTabID : " + info.startTabID);
    wf_body_bottom.getObj("scwin").setReturnValue("info.endTabID : " + info.endTabID);
    wf_body_bottom.getObj("scwin").setReturnValue("info.endTabIndex : " + info.endTabIndex);

    if (returnValue == "true")
        return true;
    else if (returnValue == "false")
        return false;
    else
        return;
}



scwin.target1_onaftertabmove = function (info) {   
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onaftertabmove=====");
}



scwin.target1_onbeforeselect = function (info) {   
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onbeforeselect=====");
}



scwin.target1_onchange = function (tabId, index, userTabId) {   
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onchange=====");
}
